<?php
namespace App\Jobs;use App\Contracts\ProtectedMediaStorage;use App\Models\{MediaExport,Photo,User};use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\{InteractsWithQueue,SerializesModels};use Illuminate\Queue\Middleware\WithoutOverlapping;use Illuminate\Support\Facades\Gate;use Illuminate\Support\Str;use RuntimeException;use Throwable;use ZipArchive;
class GenerateMediaExport implements ShouldQueue {use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public int $tries=3;public int $timeout=600;public function __construct(public int $exportId){$this->onQueue('exports');}public function backoff():array{return[30,120,300];}public function middleware():array{return[(new WithoutOverlapping('media-export-'.$this->exportId))->expireAfter(700)->dontRelease()];}public function handle(ProtectedMediaStorage $storage):void{$export=MediaExport::findOrFail($this->exportId);if($export->cancelled_at)return;$export->update(['state'=>'processing']);$user=User::findOrFail($export->user_id);$tmp=tempnam(sys_get_temp_dir(),'lenspic-export-');$zip=new ZipArchive;if($zip->open($tmp,ZipArchive::OVERWRITE)!==true)throw new RuntimeException('Archive creation failed.');try{foreach(Photo::with('mediaAsset.variants')->whereIn('id',$export->photo_ids)->get()as$photo){if($photo->group_id!==$export->group_id||Gate::forUser($user)->denies('view',$photo))continue;$variant=$photo->mediaAsset?->variant('original');if(!$variant||!$storage->exists($variant->object_key))continue;$stream=$storage->readStream($variant->object_key);$bytes=stream_get_contents($stream);fclose($stream);$extension=pathinfo($variant->object_key,PATHINFO_EXTENSION)?:'jpg';$zip->addFromString('photo-'.$photo->id.'-'.Str::uuid().'.'.$extension,$bytes);}$zip->close();$bytes=file_get_contents($tmp);if(!$bytes)throw new RuntimeException('No authorized media was available.');$key='media/exports/'.$export->user_id.'/'.Str::uuid().'.zip';$storage->put($key,$bytes,'application/zip');$export->update(['state'=>'completed','storage_disk'=>$storage->disk(),'object_key'=>$key,'size_bytes'=>strlen($bytes),'checksum_sha256'=>hash('sha256',$bytes),'expires_at'=>now()->addMinutes((int)config('media.export_ttl_minutes',60)),'error'=>null]);}catch(Throwable$e){$zip->close();$export->update(['state'=>'failed','error'=>'Archive generation failed.']);throw$e;}finally{if(is_file($tmp))@unlink($tmp);}}}
